    },
    {
      "acao": "Explique como o processador coordena o funcionamento dos componentes para melhorar a completude da resposta.",
      "nivel": "PROCESSO"
    },
    {
      "acao": "Revise sua resposta perguntando: 'Expliquei claramente como o processador executa as instruções e controla o sistema?'",
      "nivel": "AUTORREGULACAO"
    }
